// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Obtém os dados de entrada combinados pelo Merge
const dados = $input.first().json;

// 2. Extrai os clientes e a lista de investimentos
// (Caso estejam no body ou direto no objeto, garantimos o acesso)
const clientes = dados.body?.clientes || dados.clientes || [];
const investimentos = dados.investimentos || [];

// Função auxiliar para sortear uma mensagem amigável caso haja mais de uma
function pick(arr) {
  if (!arr || arr.length === 0) return "";
  return arr[Math.floor(Math.random() * arr.length)];
}

// 3. Processa cada cliente cruzando com o perfil de investimento
const resultados = clientes.map(cliente => {
  const nome = cliente.nome || cliente.name;
  const email = cliente.email;
  const perfil = (cliente.perfil || "").trim();
  const saldoTexto = cliente.saldo || "0";

  // Limpa o saldo para valor numérico caso seja necessário
  const saldoNum = typeof saldoTexto === "number" 
    ? saldoTexto 
    : parseFloat(String(saldoTexto).replace(/[^0-9,-]/g, '').replace(',', '.')) || 0;

  // Busca o investimento que corresponde ao perfil do cliente
  const investimentoEncontrado = investimentos.find(inv => 
    (inv.perfil || inv.Perfil || "").toLowerCase() === perfil.toLowerCase()
  );

  const produtoEscolhido = investimentoEncontrado 
    ? (investimentoEncontrado.investimento || investimentoEncontrado.produto || investimentoEncontrado.nome || "CDB Pós-fixado")
    : "Reserva de Emergência em CDI";

  const motivo = investimentoEncontrado?.motivo || "Adequado aos seus objetivos e nível de tolerância a risco.";

  // Exemplos de mensagens para o cliente
  const mensagens = [
    `Olá ${nome}, com base no seu perfil ${perfil}, recomendamos investir em ${produtoEscolhido}.`,
    `${nome}, identificamos que a melhor opção para seu perfil ${perfil} é ${produtoEscolhido}. ${motivo}`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao_escolhida: produtoEscolhido,
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 4. Retorno no formato exato que o nó Respond to Webhook espera (mostrado no vídeo)
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

// 1. Pega os dados que vieram do nó anterior
const dados = $input.first().json;
const resultados = dados.resultados || [];

// 2. Monta o briefing/prompt do e-mail para cada cliente
const clientesComPrompt = resultados.map(cliente => {
  const primeiroNome = (cliente.nome || "Cliente").split(" ")[0];

  const promptTexto = `Você é um consultor financeiro sênior especializado em investimentos, com comunicação empática, clara e profissional.

Seu objetivo é redigir um e-mail personalizado para o cliente com os seguintes dados:
- Nome: ${cliente.nome}
- Perfil de Risco: ${cliente.perfil}
- Saldo em Conta: ${cliente.saldo_texto}
- Recomendação de Investimento: ${cliente.recomendacao_escolhida}
- Motivo Técnico: ${cliente.motivo}

Diretrizes obrigatórias:
1. Cumprimente o cliente chamando-o por "${primeiroNome}".
2. Explique com clareza por que o produto "${cliente.recomendacao_escolhida}" é o ideal para o perfil ${cliente.perfil}.
3. Destaque como o saldo de ${cliente.saldo_texto} pode render com segurança.
4. Use linguagem simples, encorajadora e sem jargões desnecessários.
5. Finalize convidando para uma conversa rápida caso queira tirar dúvidas.

Retorne no formato:
Assunto: [Assunto atraente]
Corpo: [Texto completo do e-mail]`;

  return {
    ...cliente,
    primeiro_nome: primeiroNome,
    assunto_sugerido: `Oportunidade de investimento para você, ${primeiroNome}`,
    prompt_email: promptTexto
  };
});

// 3. Devolve uma lista de itens (um item para cada cliente)
// Isso permite que o próximo nó (IA ou Envio de E-mail) processe cliente por cliente!
return clientesComPrompt.map(item => ({ json: item }));

