// Pega os itens da IA e os itens com os dados originais dos clientes
const itensIA = $input.all();
const itensCliente = $("Code in JavaScript2").all();

return itensIA.map((item, index) => {
  // Pega o cliente correspondente a este item
  const cliente = itensCliente[index]?.json || {};
  const dadosIA = item.json;

  // 1. Extrai o texto da IA com segurança
  let textoIA = "";
  if (dadosIA.output && Array.isArray(dadosIA.output)) {
    textoIA = dadosIA.output.map(o => o.text || o.content || JSON.stringify(o)).join("\n");
  } else if (typeof dadosIA.output === "object" && dadosIA.output !== null) {
    if (dadosIA.output.text) textoIA = dadosIA.output.text;
    else if (dadosIA.output.content) {
      textoIA = Array.isArray(dadosIA.output.content) 
        ? dadosIA.output.content.map(c => c.text || "").join("\n") 
        : String(dadosIA.output.content);
    } else {
      textoIA = JSON.stringify(dadosIA.output);
    }
  } else if (typeof dadosIA.text === "string") {
    textoIA = dadosIA.text;
  } else if (typeof dadosIA.content === "string") {
    textoIA = dadosIA.content;
  } else {
    textoIA = String(dadosIA.output || "");
  }

  // 2. Extrai Assunto e Corpo
  let assunto = `Oportunidade para seu perfil, ${cliente.primeiro_nome || cliente.nome || ""}`.trim();
  let corpo = textoIA;

  const matchAssunto = textoIA.match(/Assunto:\s*(.+)/i);
  if (matchAssunto) {
    assunto = matchAssunto[1].replace(/Corpo:.*/i, '').trim();
  }

  const matchCorpo = textoIA.match(/Corpo:\s*([\s\S]+)/i);
  if (matchCorpo) {
    corpo = matchCorpo[1].trim();
  } else if (matchAssunto) {
    corpo = textoIA.replace(/Assunto:\s*.+/i, '').trim();
  }

  // Converte quebras de linha para HTML
  const corpoHtml = corpo
    .split('\n\n')
    .map(p => `<p>${p.replace(/\n/g, '<br>')}</p>`)
    .join('');

  return {
    json: {
      to: cliente.email || cliente.email_destinatario || "cliente@email.com",
      nome: cliente.nome,
      primeiro_nome: cliente.primeiro_nome,
      subject: assunto,
      corpo_texto: corpo,
      corpo_html: corpoHtml
    }
  };
});
